/**
 * Desafio+ — services/api.js
 * Cliente axios pré-configurado + todos os named exports que os componentes usam.
 *
 * Componentes que importam daqui:
 *   PostCard.js        → { postsAPI }
 *   useFeed.js         → { feedAPI }
 *   useNotifications.js→ { notificationsAPI }
 *   Challenges.js      → { challengesAPI }
 *   Chat.js            → { chatAPI }
 *   Feed.js            → { uploadAPI, postsAPI }
 *   Games.js           → { gamesAPI }
 *   Profile.js         → { usersAPI }
 *   Search.js          → { searchAPI }
 *   Settings.js        → { usersAPI }
 *   Navbar.js          → { searchAPI }
 */

import axios from 'axios';

// ── Instância base ────────────────────────────────────────────
const api = axios.create({
  baseURL: process.env.REACT_APP_API_URL || 'http://localhost:8787/api',
  timeout: 15000,
  headers: { 'Content-Type': 'application/json' },
});

// ── Interceptor: injeta token automaticamente ─────────────────
api.interceptors.request.use((config) => {
  const token = localStorage.getItem('access_token');
  if (token) config.headers.Authorization = `Bearer ${token}`;
  return config;
});

// ── Interceptor: trata token expirado ────────────────────────
api.interceptors.response.use(
  (res) => res,
  async (err) => {
    const original = err.config;
    if (
      err.response?.status === 401 &&
      err.response?.data?.code === 'TOKEN_EXPIRED' &&
      !original._retry
    ) {
      original._retry = true;
      try {
        const refreshToken = localStorage.getItem('refresh_token');
        const { data } = await axios.post(
          `${api.defaults.baseURL}/auth/refresh`,
          { refresh_token: refreshToken }
        );
        localStorage.setItem('access_token', data.access_token);
        if (data.refresh_token) localStorage.setItem('refresh_token', data.refresh_token);
        original.headers.Authorization = `Bearer ${data.access_token}`;
        return api(original);
      } catch {
        localStorage.removeItem('access_token');
        localStorage.removeItem('refresh_token');
        window.location.href = '/login';
      }
    }
    return Promise.reject(err);
  }
);

// ── Posts ─────────────────────────────────────────────────────
export const postsAPI = {
  getAll:      (params)       => api.get('/posts', { params }),
  getById:     (id)           => api.get(`/posts/${id}`),
  create:      (data)         => api.post('/posts', data),
  update:      (id, data)     => api.put(`/posts/${id}`, data),
  delete:      (id)           => api.delete(`/posts/${id}`),
  like:        (id)           => api.post(`/posts/${id}/like`),
  unlike:      (id)           => api.delete(`/posts/${id}/like`),
  getComments: (id, params)   => api.get(`/posts/${id}/comments`, { params }),
  addComment:  (id, data)     => api.post(`/posts/${id}/comments`, data),
  deleteComment:(postId, cId) => api.delete(`/posts/${postId}/comments/${cId}`),
};

// ── Feed ──────────────────────────────────────────────────────
export const feedAPI = {
  getFeed:    (params) => api.get('/feed', { params }),
  getExplore: (params) => api.get('/feed/explore', { params }),
  getTimeline:(params) => api.get('/feed/timeline', { params }),
};

// ── Notificações ──────────────────────────────────────────────
export const notificationsAPI = {
  getAll:        (params) => api.get('/notifications', { params }),
  getUnreadCount:()       => api.get('/notifications/unread-count'),
  markAsRead:    (id)     => api.patch(`/notifications/${id}/read`),
  markAllRead:   ()       => api.patch('/notifications/read-all'),
  delete:        (id)     => api.delete(`/notifications/${id}`),
};

// ── Desafios ──────────────────────────────────────────────────
export const challengesAPI = {
  getAll:    (params) => api.get('/challenges', { params }),
  getDaily:  ()       => api.get('/challenges/daily'),
  getById:   (id)     => api.get(`/challenges/${id}`),
  create:    (data)   => api.post('/challenges', data),
  join:      (id)     => api.post(`/challenges/${id}/join`),
  accept:    (id)     => api.post(`/challenges/${id}/accept`),
  complete:  (id, d)  => api.post(`/challenges/${id}/complete`, d),
  generateAI:(data)   => api.post('/challenges/generate-ai', data),
};

// ── Chat ──────────────────────────────────────────────────────
export const chatAPI = {
  getConversations: (params) => api.get('/chat/conversations', { params }),
  getMessages:      (id, p)  => api.get(`/chat/conversations/${id}/messages`, { params: p }),
  sendMessage:      (id, d)  => api.post(`/chat/conversations/${id}/messages`, d),
  createConversation:(data)  => api.post('/chat/conversations', data),
  markRead:         (id)     => api.patch(`/chat/conversations/${id}/read`),
};

// ── Upload ────────────────────────────────────────────────────
export const uploadAPI = {
  /** Solicita URL pré-assinada para upload direto ao R2 */
  getPresignUrl: (data) => api.post('/upload/presign', data),
  /** Upload direto para URL pré-assinada (sem passar pelo backend) */
  uploadToR2: async (file, folder = 'posts') => {
    const mime = file.type || 'image/jpeg';
    const { data } = await api.post('/upload/presign', { folder, mimetype: mime });
    await fetch(data.uploadUrl, {
      method: 'PUT',
      body: file,
      headers: { 'Content-Type': mime },
    });
    return data.publicUrl;
  },
  /** Upload via multipart (fallback local) */
  upload: (formData) => api.post('/upload', formData, {
    headers: { 'Content-Type': 'multipart/form-data' },
  }),
};

// ── Jogos ─────────────────────────────────────────────────────
export const gamesAPI = {
  getAll:        ()       => api.get('/games'),
  getLeaderboard:(gameId) => api.get(`/games/${gameId}/leaderboard`),
  getScores:     (gameId) => api.get(`/games/${gameId}/scores`),
  submitScore:   (data)   => api.post('/games/score', data),
  recordSession: (data)   => api.post('/games/session', data),
};

// ── Usuários ──────────────────────────────────────────────────
export const usersAPI = {
  getProfile:    (username) => api.get(`/users/${username}`),
  getMyProfile:  ()         => api.get('/users/me'),
  getPosts:      (username, params) => api.get(`/users/${username}/posts`, { params }),
  updateProfile: (data)     => api.put('/users/me', data),
  follow:        (id)       => api.post(`/users/${id}/follow`),
  unfollow:      (id)       => api.delete(`/users/${id}/follow`),
  getFollowers:  (id)       => api.get(`/users/${id}/followers`),
  getFollowing:  (id)       => api.get(`/users/${id}/following`),
  search:        (q)        => api.get('/users/search', { params: { q } }),
  block:         (id)       => api.post(`/blocks/${id}/block`),
  unblock:       (id)       => api.delete(`/blocks/${id}/block`),
};

// ── Busca ─────────────────────────────────────────────────────
export const searchAPI = {
  search: (q, type = 'all', limit = 10) =>
    api.get('/search', { params: { q, type, limit } }),
};

// ── Auth (usado pelo AuthContext) ─────────────────────────────
export const authAPI = {
  register:  (data) => api.post('/auth/register', data),
  login:     (data) => api.post('/auth/login', data),
  me:        ()     => api.get('/auth/me'),
  refresh:   (data) => api.post('/auth/refresh', data),
  logout:    ()     => api.post('/auth/logout'),
  updateProfile: (data) => api.put('/auth/profile', data),
};

export default api;
